```rust
use std::collections::HashMap;
use std::fs::File;
use std::io::{BufRead, BufReader};

/// Parses a configuration file containing sections and 'key = value' lines.
/// 
/// Section headers are denoted by `[section_name]`. Keys defined under a section
/// are stored in the map as `"{section}.{key}"`. Global keys (outside any section)
/// remain as-is. Blank lines and lines starting with '#' are ignored. Lines that
/// do not contain exactly one '=' sign or have empty keys/values after trimming
/// will result in an error. Malformed sections (missing brackets, empty names) 
/// also cause errors.
/// 
/// # Arguments
/// * `path` - A string slice representing the file path to parse.
/// 
/// # Returns
/// * `Ok(HashMap)` containing the parsed key-value pairs with section prefixes.
/// * `Err(ConfigParseError)` if the file cannot be read or contains invalid lines.
pub fn parse_config_file(path: &str) -> Result<HashMap<String, String>, ConfigParseError> {
    let file = File::open(path)?;

    let reader = BufReader::new(file);
    let mut config_map = HashMap::new();
    let mut current_section: Option<String> = None;

    for line in reader.lines() {
        // Convert the result of reading a line to an Option. 
        // If reading fails (e.g., EOF mid-line), we treat it as an IO error.
        let line_content = match line {
            Ok(l) => l,
            Err(e) => return Err(ConfigParseError::Io(e)),
        };

        // Skip blank lines and comments
        if line_content.is_empty() || line_content.starts_with('#') {
            continue;
        }

        // Check for section header: starts with '[' and ends with ']'
        let trimmed_line = line_content.trim();

        if trimmed_line.starts_with('[') && trimmed_line.ends_with(']') {
            let inner_content = &trimmed_line[1..trimmed_line.len() - 1];

            // Ensure the section name is not empty after trimming brackets
            if inner_content.is_empty() {
                return Err(ConfigParseError::MalformedSection(line_content));
            }

            current_section = Some(inner_content.to_string());
            continue;
        }

        // Attempt to split the line into key and value. 
        // We use splitn(2) to handle values containing '=' signs correctly.
        let parts: Vec<&str> = trimmed_line.splitn(2, '=').collect();

        if parts.len() != 2 {
            return Err(ConfigParseError::InvalidFormat(line_content));
        }

        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        // Ensure keys are not empty after trimming to prevent infinite loops or confusion
        if key.is_empty() {
            return Err(ConfigParseError::InvalidFormat(line_content));
        }

        // Construct the final key based on whether a section is active
        let final_key = match current_section.as_ref() {
            Some(section) => format!("{}.{}", section, key),
            None => key,
        };

        config_map.insert(final_key, value);
    }

    Ok(config_map)
}
```

