### The Parser Module

We encapsulate the logic in a module to keep the namespace clean. We use `std::collections::HashMap` for storage.

```rust
use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead};

/// Represents errors that can occur during configuration parsing.
pub enum ConfigError {
    Io(io::Error),
    InvalidFormat(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "Failed to read config file: {}", e),
            ConfigError::InvalidFormat(msg) => write!(f, "Invalid configuration format: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::Io(e) => Some(e),
            _ => None,
        }
    }
}

/// Parses a configuration file containing lines in the format `key = value`.
/// 
/// Lines starting with '#' or blank lines are ignored.
/// The function returns a `Result` containing the populated HashMap or an error.
pub fn parse_config(path: &str) -> Result<HashMap<String, String>, ConfigError> {
    let file = fs::File::open(path)?;

    // Use BufReader to handle large files efficiently without loading everything into memory at once
    let reader = io::BufReader::new(file);

    let mut config: HashMap<String, String> = HashMap::new();

    for line in reader.lines() {
        let line_content = line?;

        // Skip blank lines and comments using filter_map logic manually or via iterator chaining
        if line_content.is_empty() || line_content.starts_with('#') {
            continue;
        }

        // Split on the first '=' only. 
        // If no '=' is found, split will return an iterator with a single element.
        let parts: Vec<&str> = line_content.splitn(2, '=').collect();

        if parts.len() != 2 {
            return Err(ConfigError::InvalidFormat(line_content.clone()));
        }

        // Trim whitespace from key and value to handle "key = value" vs "key=value"
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        if key.is_empty() {
            return Err(ConfigError::InvalidFormat(line_content.clone()));
        }

        config.insert(key, value);
    }

    Ok(config)
}
```

