    /// The file could not be read or does not exist.
    Io(std::io::Error),
    /// A line in the config file did not match the expected 'key = value' format.
    InvalidFormat(String),
    /// A section header was malformed (e.g., missing brackets).
    InvalidSection(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "Failed to read config file: {}", e),
            ConfigError::InvalidFormat(msg) => write!(f, "Invalid configuration format: {}", msg),
            ConfigError::InvalidSection(msg) => write!(f, "Invalid section header: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::Io(e) => Some(e),
            _ => None,
        }
    }
}
```

### The Parser Module with Section Support

We introduce a `current_section` variable to track the active context. We use an iterator over lines and handle state transitions within the loop.

```rust
use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead};

/// Represents errors that can occur during configuration parsing.
pub enum ConfigError {
    Io(io::Error),
    InvalidFormat(String),
    InvalidSection(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "Failed to read config file: {}", e),
            ConfigError::InvalidFormat(msg) => write!(f, "Invalid configuration format: {}", msg),
            ConfigError::InvalidSection(msg) => write!(f, "Invalid section header: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ConfigError::Io(e) => Some(e),
            _ => None,
        }
    }
}

/// Parses a configuration file supporting sections in the format `[section]`.
/// 
/// - Lines starting with '#' or blank lines are ignored.
/// - Section headers are defined as `[section_name]`.
/// - Keys under a section are stored as `section_name.key = value`.
/// - Keys outside of any section are stored directly as `key = value`.
pub fn parse_config(path: &str) -> Result<HashMap<String, String>, ConfigError> {
    let file = fs::File::open(path)?;

    // Use BufReader to handle large files efficiently without loading everything into memory at once
    let reader = io::BufReader::new(file);

    let mut config: HashMap<String, String> = HashMap::new();
    let mut current_section: Option<String> = None;

    for line in reader.lines() {
        // Propagate I/O errors immediately instead of unwrapping
        let line_content = line?;

        // Trim whitespace to handle indentation and trailing spaces cleanly
        let trimmed_line = line_content.trim();

        // Skip blank lines and comments using explicit checks within the iterator loop
        if trimmed_line.is_empty() || trimmed_line.starts_with('#') {
            continue;
        }

        // Check for section header: must start with '[' and end with ']'
        if let Some(section_name) = parse_section_header(trimmed_line) {
            current_section = Some(section_name);
            continue;
        }

        // Attempt to parse as key-value pair
        let (key, value) = parse_key_value(trimmed_line)?;

        // Construct the full key based on active section context
        let final_key = match &current_section {
            Some(sec) => format!("{}.{}", sec, key),
            None => key.clone(),
        };

        config.insert(final_key, value);
    }

    Ok(config)
}

/// Extracts the section name from a line like `[database]`.
/// Returns `None` if the line is not a valid section header.
fn parse_section_header(line: &str) -> Option<String> {
    // Check strict format: starts with [ and ends with ]
    if !line.starts_with('[') || !line.ends_with(']') {
        return None;
    }

    let inner = line[1..line.len() - 1].trim();

    // Ensure the content inside brackets is not empty after trimming
    if inner.is_empty() {
        return None;
    }

    Some(inner.to_string())
}

/// Parses a single line into a key-value pair.
/// Returns an error if the format is invalid (missing '=' or empty key).
fn parse_key_value(line: &str) -> Result<(String, String), ConfigError> {
    // Split on the first '=' only to support values containing '='
    let parts: Vec<&str> = line.splitn(2, '=').collect();

    if parts.len() != 2 {
        return Err(ConfigError::InvalidFormat(line.to_string()));
    }

    let key = parts[0].trim().to_string();
    let value = parts[1].trim().to_string();

    // Keys must not be empty after trimming
    if key.is_empty() {
        return Err(ConfigError::InvalidFormat(line.to_string()));
    }

    Ok((key, value))
}
```

